#!/usr/bin/env bash
# valkey TLS: install the instances' certificate and key generated by
# OpenTofu (tls_self_signed_cert.valkey in proxmox/opentofu/valkey.tf: the
# CT's name and IP, so clients can pin it, e.g. Kubeletto's REDIS_TLS_CA).
# Run by terraform_data.valkey_tls after setup.sh, before instances.sh.
#
# stdin: the certificate PEM, then the private key PEM. The key never touches
# argv or the repo. Running instances restart only when the pair changed
# (a restart empties their cache).
set -euo pipefail

d=/etc/valkey/tls
in=$(cat)
cert=$(printf '%s\n' "$in" | sed -n '/-----BEGIN CERTIFICATE-----/,/-----END CERTIFICATE-----/p')
key=$(printf '%s\n' "$in" | sed -n '/-----BEGIN [A-Z ]*PRIVATE KEY-----/,/-----END [A-Z ]*PRIVATE KEY-----/p')
[ -n "$cert" ] && [ -n "$key" ] || { echo "expected a certificate and a private key on stdin" >&2; exit 1; }

umask 027
install -d -o root -g valkey -m 0750 "$d"
printf '%s\n' "$cert" > "$d/.cert.new"
printf '%s\n' "$key" > "$d/.key.new"
# the pair must match before it replaces the running one
[ "$(openssl x509 -in "$d/.cert.new" -noout -pubkey)" = "$(openssl pkey -in "$d/.key.new" -pubout)" ] ||
  { rm -f "$d/.cert.new" "$d/.key.new"; echo "certificate and key do not match" >&2; exit 1; }
chown root:valkey "$d/.cert.new" "$d/.key.new"
chmod 0644 "$d/.cert.new"
chmod 0640 "$d/.key.new"

if cmp -s "$d/.cert.new" "$d/cert.pem" && cmp -s "$d/.key.new" "$d/key.pem"; then
  rm -f "$d/.cert.new" "$d/.key.new"
  echo "valkey tls: unchanged"
  exit 0
fi
mv "$d/.cert.new" "$d/cert.pem"
mv "$d/.key.new" "$d/key.pem"
for unit in $(systemctl list-units --plain --no-legend 'valkey-server@*' | awk '{print $1}'); do
  systemctl restart "$unit"
done
echo "valkey tls: installed $(openssl x509 -in "$d/cert.pem" -noout -subject -enddate | tr '\n' ' ')"
